#!/usr/bin/env python3
import sys, os, re, json, html as htmlmod
from html.parser import HTMLParser
from collections import OrderedDict, defaultdict

Y='\033[33m'; G='\033[32m'; B='\033[94m'; R='\033[0m'
HELP = """Command-line XML and HTML beautifier and content extractor

Usage:
  xq [flags]

Flags:
  -a, --attr string      Extract an attribute value instead of node content for provided CSS query
  -c, --color            Force colorful output
      --compact          Compact JSON output (no indentation)
  -d, --depth int        Maximum nesting depth for JSON output (-1 for unlimited) (default -1)
  -e, --extract string   Extract a single node from XML
  -h, --help             Print this help message
  -m, --html             Use HTML formatter
  -i, --in-place         Format file in place
      --indent int       Use the given number of spaces for indentation (default 2)
  -j, --json             Output the result as JSON
      --no-color         Disable colorful output
  -n, --node             Return the node content instead of text
  -q, --query string     Extract the node(s) using CSS selector
      --tab              Use tabs for indentation
  -v, --version          Print version information
  -x, --xpath string     Extract the node(s) from XML
"""

VOID_TAGS = set('area base br col embed hr img input link meta param source track wbr command keygen menuitem'.split())

class Options:
    def __init__(self):
        self.attr = ''
        self.color = False
        self.no_color = False
        self.compact = False
        self.depth = -1
        self.extract = ''
        self.html = False
        self.in_place = False
        self.indent = 2
        self.json = False
        self.node = False
        self.query = ''
        self.query_set = False
        self.tab = False
        self.xpath = ''
        self.xpath_set = False
        self.files = []


def parse_int_flag(val, flagdesc):
    try:
        return int(val, 10)
    except Exception:
        return None


def parse_args(argv):
    opt = Options()
    i=0
    value_flags = {
        '--attr':'attr','-a':'attr',
        '--depth':'depth','-d':'depth',
        '--extract':'extract','-e':'extract',
        '--indent':'indent',
        '--query':'query','-q':'query',
        '--xpath':'xpath','-x':'xpath',
    }
    bool_flags = {
        '--color':'color','-c':'color','--compact':'compact','--html':'html','-m':'html',
        '--in-place':'in_place','-i':'in_place','--json':'json','-j':'json',
        '--no-color':'no_color','--node':'node','-n':'node','--tab':'tab'
    }
    while i < len(argv):
        a = argv[i]
        if a == '--':
            opt.files.extend(argv[i+1:]); break
        if a in ('--help','-h'):
            sys.stdout.write(HELP); sys.exit(0)
        if a in ('--version','-v'):
            sys.stdout.write('xq version 1.4.0\n'); sys.exit(0)
        # long --flag=value
        if a.startswith('--') and '=' in a:
            name,val = a.split('=',1)
            if name in value_flags:
                field=value_flags[name]
                if field in ('indent','depth'):
                    n=parse_int_flag(val, name)
                    if n is None:
                        desc = '"%s"' % name if field=='indent' else '"-d, --depth"'
                        sys.stderr.write(f'Error: invalid argument "{val}" for {desc} flag: strconv.ParseInt: parsing "{val}": invalid syntax\n')
                        sys.exit(1)
                    setattr(opt, field, n)
                else:
                    setattr(opt, field, val)
                    if field == 'query': opt.query_set=True
                    if field == 'xpath': opt.xpath_set=True
                i+=1; continue
            elif name in bool_flags:
                # pflag accepts --bool=true; keep simple
                truth = val.lower() not in ('0','false','no')
                setattr(opt, bool_flags[name], truth); i+=1; continue
            else:
                sys.stderr.write(f'Error: unknown flag: {name}\n'); sys.exit(1)
        if a in value_flags:
            if i+1 >= len(argv):
                sys.stderr.write(f'Error: flag needs an argument: {a}\n'); sys.exit(1)
            val=argv[i+1]; field=value_flags[a]
            if field in ('indent','depth'):
                n=parse_int_flag(val, a)
                if n is None:
                    desc = '"--indent"' if field=='indent' else '"-d, --depth"'
                    sys.stderr.write(f'Error: invalid argument "{val}" for {desc} flag: strconv.ParseInt: parsing "{val}": invalid syntax\n')
                    sys.exit(1)
                setattr(opt, field, n)
            else:
                setattr(opt, field, val)
                if field == 'query': opt.query_set=True
                if field == 'xpath': opt.xpath_set=True
            i+=2; continue
        if a in bool_flags:
            setattr(opt, bool_flags[a], True); i+=1; continue
        # support compact short bool groups such as -cnm, and -xVALUE/-qVALUE lightly
        if a.startswith('-') and a != '-':
            if len(a) > 2 and a[1] in ('x','q','e','a','d'):
                short='-'+a[1]; val=a[2:]
                field=value_flags.get(short)
                if field in ('depth',):
                    n=parse_int_flag(val, short)
                    if n is None:
                        sys.stderr.write(f'Error: invalid argument "{val}" for "-d, --depth" flag: strconv.ParseInt: parsing "{val}": invalid syntax\n'); sys.exit(1)
                    opt.depth=n
                elif field:
                    setattr(opt, field, val)
                    if field=='query': opt.query_set=True
                    if field=='xpath': opt.xpath_set=True
                i+=1; continue
            if len(a)>2 and all(('-'+ch) in bool_flags for ch in a[1:]):
                for ch in a[1:]: setattr(opt, bool_flags['-'+ch], True)
                i+=1; continue
            sys.stderr.write(f'Error: unknown shorthand flag: {a[1:2]} in {a}\n'); sys.exit(1)
        opt.files.append(a); i+=1
    if opt.indent < 0 or opt.indent > 8:
        sys.stderr.write('Error: indent should be between 0-8 spaces\n'); sys.exit(1)
    return opt


def use_color(opt):
    if opt.color: return True
    if opt.no_color: return False
    try: return sys.stdout.isatty()
    except Exception: return False


def esc_attr(v):
    if v is None: v=''
    v = str(v)
    return v.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;').replace("'",'&apos;')

def unesc(v):
    if v is None: return ''
    return htmlmod.unescape(v)


def find_tag_end(s, start):
    quote=None; i=start
    while i < len(s):
        c=s[i]
        if quote:
            if c == quote: quote=None
        else:
            if c in ('"',"'"): quote=c
            elif c == '>': return i
        i+=1
    return -1


def parse_attrs(rest, html_mode=False):
    attrs=[]; i=0; n=len(rest)
    while i<n:
        while i<n and rest[i].isspace(): i+=1
        if i>=n: break
        # skip stray slash
        if rest[i] == '/': i+=1; continue
        st=i
        while i<n and not rest[i].isspace() and rest[i] not in ['=','/','>']:
            i+=1
        name=rest[st:i]
        if not name: break
        while i<n and rest[i].isspace(): i+=1
        val = '' if html_mode else name
        if i<n and rest[i]=='=':
            i+=1
            while i<n and rest[i].isspace(): i+=1
            if i<n and rest[i] in ('"',"'"):
                q=rest[i]; i+=1; st=i
                while i<n and rest[i]!=q: i+=1
                val=rest[st:i]
                if i<n and rest[i]==q: i+=1
            else:
                st=i
                while i<n and not rest[i].isspace() and rest[i] not in ['>']:
                    i+=1
                val=rest[st:i]
        attrs.append((name, unesc(val)))
    return attrs


def split_tag_content(content, html_mode=False):
    content=content.strip()
    selfclose=False
    if content.endswith('/'):
        selfclose=True; content=content[:-1].rstrip()
    if not content:
        return '', [], selfclose
    m=re.match(r'([^\s/>]+)(.*)$', content, re.S)
    if not m: return content, [], selfclose
    name=m.group(1); rest=m.group(2)
    return name, parse_attrs(rest, html_mode), selfclose

class StackItem:
    __slots__=('name','open','has_element','has_text','has_nonvoid')
    def __init__(self,name,open=True):
        self.name=name; self.open=open; self.has_element=False; self.has_text=False; self.has_nonvoid=False

class StreamFormatter:
    def __init__(self, indent_unit='  ', color=False, mode='xml'):
        self.indent_unit=indent_unit
        self.color=color
        self.mode=mode
        self.parts=[]
        self.stack=[]
        self.last=None
    def depth(self): return len(self.stack)
    def append(self,x): self.parts.append(x)
    def newline(self, depth):
        if self.indent_unit == '': return
        self.append('\n' + self.indent_unit*max(depth,0))
    def tag_open(self,name):
        return (Y+('<'+name)+R) if self.color else '<'+name
    def tag_gt(self): return (Y+'>'+R) if self.color else '>'
    def tag_self(self): return (Y+'/>'+R) if self.color else '/>'
    def tag_close(self,name): return (Y+('</'+name+'>')+R) if self.color else '</'+name+'>'
    def attrs_s(self, attrs):
        out=[]
        for k,v in attrs:
            if self.color:
                out.append(' '+k+G+'="'+esc_attr(v)+'"'+R)
            else:
                out.append(' '+k+'="'+esc_attr(v)+'"')
        return ''.join(out)
    def close_open(self, empty=False, lastval=None):
        if self.stack and self.stack[-1].open:
            if empty:
                self.append(self.tag_self())
                self.stack.pop()
                self.last = lastval or 'end'
            else:
                self.append(self.tag_gt())
                self.stack[-1].open=False
    def before_start(self):
        if self.stack and self.stack[-1].open:
            self.close_open(False)
        d=self.depth()
        # newlines are only used inside an element; top-level siblings stay adjacent.
        if self.parts and d>0 and self.indent_unit!='':
            self.newline(d)
        elif self.parts and d==0 and self.last in ('directive','pi') and self.indent_unit!='':
            self.newline(0)
    def start(self,name,attrs,selfclose=False, void=False):
        # mark parent child-ness before pushing
        if self.stack:
            self.stack[-1].has_element=True
            if self.mode=='html' and not void:
                self.stack[-1].has_nonvoid=True
        self.before_start()
        self.append(self.tag_open(name)+self.attrs_s(attrs))
        if self.mode=='html' and void:
            self.append(self.tag_self())
            self.last='void'
            return
        self.stack.append(StackItem(name, True))
        if selfclose:
            self.close_open(True)
        else:
            self.last='start'
    def text(self,t):
        if t is None or t=='': return
        t=t.replace('\r\n','\n').replace('\r','\n')
        if t.strip()=='': return
        # XML/HTML formatters trim ordinary trailing spaces but preserve tabs/newlines.
        t=t.rstrip(' ')
        if self.stack and self.stack[-1].open:
            self.close_open(False)
        if self.stack:
            self.stack[-1].has_text=True
        if self.mode=='xml' and ('&' in t or '<' in t):
            t='<![CDATA['+t+']]>'
        self.append(t)
        self.last='text'
    def comment(self,c):
        if self.stack and self.stack[-1].open:
            self.close_open(False)
        d=self.depth()
        if self.parts and d>0 and self.last!='text' and self.indent_unit!='':
            self.newline(d)
        if self.color:
            if self.mode=='html':
                self.append(B+'<!--'+c+'-->'+R)
            else:
                self.append(B+'<!--'+R+B+c+R+B+'-->'+R)
        else:
            self.append('<!--'+c+'-->')
        self.last='comment'
    def directive(self,content):
        if self.stack and self.stack[-1].open: self.close_open(False)
        if self.parts and self.indent_unit!='': self.newline(0 if self.depth()==0 else self.depth())
        c=content.strip()
        if c.upper().startswith('DOCTYPE'):
            rest=c[7:].strip()
            if self.color: self.append(Y+'<!doctype '+R+rest+Y+'>'+R)
            else: self.append('<!doctype '+rest+'>')
        else:
            if self.color: self.append(Y+'<!'+R+c+Y+'>'+R)
            else: self.append('<!'+c+'>')
        self.last='directive'
    def pi(self,content):
        if self.stack and self.stack[-1].open: self.close_open(False)
        if self.parts and self.indent_unit!='': self.newline(0 if self.depth()==0 else self.depth())
        content=content.strip()
        m=re.match(r'([^\s]+)(.*)$', content, re.S)
        if not m:
            target=content; attrs=[]
        else:
            target=m.group(1); attrs=parse_attrs(m.group(2), False)
        if self.color:
            self.append(Y+'<?'+R+target+self.attrs_s(attrs)+Y+'?>'+R)
        else:
            self.append('<?'+target+self.attrs_s(attrs)+'?>')
        self.last='pi'
    def end(self,name):
        # Special XML bug: a comment-only element is rendered as if self-closed after the comment.
        if self.mode=='xml' and self.stack and self.stack[-1].name==name and self.last=='comment' and not self.stack[-1].has_element and not self.stack[-1].has_text:
            self.append(self.tag_self())
            self.stack.pop(); self.last='end'; return
        if self.stack and self.stack[-1].open:
            if self.stack[-1].name==name:
                self.close_open(True); return
            else:
                self.close_open(False)
        # find matching element (formatter is intentionally forgiving)
        idx=None
        for j in range(len(self.stack)-1,-1,-1):
            if self.stack[j].name==name:
                idx=j; break
        item = self.stack[idx] if idx is not None else None
        depth_after = idx if idx is not None else max(len(self.stack)-1,0)
        do_nl=False
        if self.indent_unit!='':
            if self.mode=='html':
                if self.last=='end': do_nl=True
                elif self.last in ('void','comment') and item is not None and item.has_nonvoid: do_nl=True
            else:
                if self.last=='end': do_nl=True
                elif self.last=='comment' and item is not None and item.has_element: do_nl=True
        if do_nl: self.newline(depth_after)
        self.append(self.tag_close(name))
        if idx is not None:
            del self.stack[idx:]
        self.last='end'
    def finish(self):
        # close a dangling open start with > (HTML malformed inputs often leave stack open)
        if self.stack and self.stack[-1].open:
            self.close_open(False)
        return ''.join(self.parts)+'\n'


def format_xml(data, opt):
    if data == '':
        return '', 'unknown content type: 3'
    indent_unit='\t' if opt.tab else (' '*opt.indent)
    color=use_color(opt)
    f=StreamFormatter(indent_unit,color,'xml')
    s=data
    pos=0
    try:
        while pos < len(s):
            lt=s.find('<',pos)
            if lt<0:
                f.text(unesc(s[pos:])); break
            if lt>pos:
                f.text(unesc(s[pos:lt]))
            # at lt
            if s.startswith('<!--',lt):
                end=s.find('-->',lt+4)
                if end<0: return f.finish().rstrip('\n'), 'XML syntax error on line 1: unexpected EOF'
                f.comment(s[lt+4:end]); pos=end+3; continue
            if s.startswith('<![CDATA[',lt):
                # The reference binary fails on CDATA in formatting mode.
                return '', "invalid character '<' looking for beginning of value"
            if s.startswith('<?',lt):
                end=s.find('?>',lt+2)
                if end<0: return f.finish().rstrip('\n'), 'XML syntax error on line 1: unexpected EOF'
                f.pi(s[lt+2:end]); pos=end+2; continue
            if s.startswith('</',lt):
                end=find_tag_end(s,lt+2)
                if end<0: return f.finish().rstrip('\n'), 'XML syntax error on line 1: unexpected EOF'
                name=s[lt+2:end].strip().split()[0] if s[lt+2:end].strip() else ''
                f.end(name); pos=end+1; continue
            if s.startswith('<!',lt):
                end=find_tag_end(s,lt+2)
                if end<0: return f.finish().rstrip('\n'), 'XML syntax error on line 1: unexpected EOF'
                f.directive(s[lt+2:end]); pos=end+1; continue
            end=find_tag_end(s,lt+1)
            if end<0:
                return f.finish().rstrip('\n'), 'XML syntax error on line 1: unexpected EOF'
            content=s[lt+1:end]
            name,attrs,selfclose=split_tag_content(content,False)
            if name:
                f.start(name,attrs,selfclose,False)
            pos=end+1
        # rudimentary unexpected EOF for unclosed non-open elements
        # The original is lenient, but a lone unclosed root errors.
        if f.stack:
            # leave partial output and report EOF
            return ''.join(f.parts), 'XML syntax error on line 1: unexpected EOF'
        return f.finish(), None
    except Exception as e:
        return f.finish(), str(e)

class FormatHTMLParser(HTMLParser):
    def __init__(self, formatter):
        super().__init__(convert_charrefs=True)
        self.f=formatter
    def handle_starttag(self, tag, attrs):
        attrs=[(k, '' if v is None else v) for k,v in attrs]
        self.f.start(tag, attrs, False, tag.lower() in VOID_TAGS)
    def handle_startendtag(self, tag, attrs):
        attrs=[(k, '' if v is None else v) for k,v in attrs]
        self.f.start(tag, attrs, True, False)
    def handle_endtag(self, tag): self.f.end(tag)
    def handle_data(self, data): self.f.text(data)
    def handle_comment(self, data): self.f.comment(data)
    def handle_decl(self, decl): self.f.directive(decl)
    def unknown_decl(self, data): self.f.directive(data)


def format_html(data,opt):
    indent_unit='\t' if opt.tab else (' '*opt.indent)
    f=StreamFormatter(indent_unit,use_color(opt),'html')
    p=FormatHTMLParser(f)
    try:
        p.feed(data)
        p.close()
    except Exception:
        pass
    return f.finish(), None

# Tree structures for extraction and JSON
class Node:
    __slots__=('tag','attrs','children','parent','void','order')
    def __init__(self, tag=None, attrs=None, parent=None, void=False):
        self.tag=tag; self.attrs=attrs or []; self.children=[]; self.parent=parent; self.void=void; self.order=0
    def append(self,ch):
        if isinstance(ch, Node): ch.parent=self
        self.children.append(ch)

class AttrResult:
    __slots__=('name','value','parent')
    def __init__(self,name,value,parent=None): self.name=name; self.value=value; self.parent=parent
class TextResult:
    __slots__=('text','parent')
    def __init__(self,text,parent=None): self.text=text; self.parent=parent


def parse_xml_tree(data, strict=False):
    root=Node(None)
    stack=[root]
    pos=0; order=1
    if data=='':
        if strict: raise ValueError('xmlquery: invalid XML document')
        return root
    while pos < len(data):
        lt=data.find('<',pos)
        if lt<0:
            txt=unesc(data[pos:].replace('\r\n','\n').replace('\r','\n'))
            if txt: stack[-1].append(txt)
            break
        if lt>pos:
            txt=unesc(data[pos:lt].replace('\r\n','\n').replace('\r','\n'))
            if txt: stack[-1].append(txt)
        if data.startswith('<!--',lt):
            end=data.find('-->',lt+4)
            if end<0:
                if strict: raise ValueError('XML syntax error on line 1: unexpected EOF')
                break
            pos=end+3; continue
        if data.startswith('<![CDATA[',lt):
            end=data.find(']]>',lt+9)
            if strict:
                raise ValueError("invalid character '<' looking for beginning of value")
            if end<0: break
            stack[-1].append(data[lt+9:end]); pos=end+3; continue
        if data.startswith('<?',lt):
            end=data.find('?>',lt+2)
            if end<0: break
            pos=end+2; continue
        if data.startswith('<!',lt):
            end=find_tag_end(data,lt+2)
            if end<0: break
            pos=end+1; continue
        if data.startswith('</',lt):
            end=find_tag_end(data,lt+2)
            if end<0:
                if strict: raise ValueError('XML syntax error on line 1: unexpected EOF')
                break
            name=data[lt+2:end].strip().split()[0] if data[lt+2:end].strip() else ''
            if len(stack)>1 and stack[-1].tag==name:
                stack.pop()
            else:
                if strict:
                    top=stack[-1].tag if len(stack)>1 else name
                    raise ValueError(f'XML syntax error on line 1: element <{top}> closed by </{name}>')
                # leniently pop matching if it exists; otherwise ignore
                for j in range(len(stack)-1,0,-1):
                    if stack[j].tag==name:
                        del stack[j:]
                        break
            pos=end+1; continue
        end=find_tag_end(data,lt+1)
        if end<0:
            if strict: raise ValueError('XML syntax error on line 1: unexpected EOF')
            break
        name,attrs,selfclose=split_tag_content(data[lt+1:end],False)
        if name:
            node=Node(name, attrs); node.order=order; order+=1
            stack[-1].append(node)
            if not selfclose:
                stack.append(node)
        pos=end+1
    if strict and len(stack)>1:
        raise ValueError('XML syntax error on line 1: unexpected EOF')
    return root

class TreeHTMLParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root=Node(None); self.stack=[self.root]; self.order=1
    def handle_starttag(self, tag, attrs):
        attrs=[(k, '' if v is None else v) for k,v in attrs]
        node=Node(tag,attrs,void=tag.lower() in VOID_TAGS); node.order=self.order; self.order+=1
        self.stack[-1].append(node)
        if tag.lower() not in VOID_TAGS:
            self.stack.append(node)
    def handle_startendtag(self, tag, attrs):
        attrs=[(k, '' if v is None else v) for k,v in attrs]
        node=Node(tag,attrs,void=True); node.order=self.order; self.order+=1
        self.stack[-1].append(node)
    def handle_endtag(self, tag):
        for j in range(len(self.stack)-1,0,-1):
            if self.stack[j].tag==tag:
                del self.stack[j:]
                break
    def handle_data(self, data):
        if data: self.stack[-1].append(data)
    def handle_comment(self, data): pass
    def handle_decl(self, decl): pass


def parse_html_tree(data, wrap=True):
    p=TreeHTMLParser(); p.feed(data); p.close(); root=p.root
    if wrap:
        has_html=any(isinstance(ch,Node) and ch.tag=='html' for ch in root.children)
        if not has_html:
            newroot=Node(None)
            htmln=Node('html'); htmln.order=1
            head=Node('head'); head.order=2
            body=Node('body'); body.order=3
            htmln.append(head); htmln.append(body)
            # reparent original children into body
            for ch in root.children:
                body.append(ch)
            newroot.append(htmln)
            # reset document order preorder
            assign_order(newroot)
            return newroot
    return root


def assign_order(root):
    c=[1]
    def rec(n):
        if isinstance(n,Node) and n.tag is not None:
            n.order=c[0]; c[0]+=1
        if isinstance(n,Node):
            for ch in n.children: rec(ch)
    rec(root)


def element_children(n): return [c for c in n.children if isinstance(c,Node)]
def all_desc(n):
    out=[]
    for ch in n.children:
        if isinstance(ch,Node):
            out.append(ch); out.extend(all_desc(ch))
    return out

def node_attr(n,name):
    for k,v in n.attrs:
        if k==name: return v
    return None

def node_text(n):
    parts=[]
    def rec(x):
        for ch in x.children:
            if isinstance(ch,Node): rec(ch)
            else: parts.append(str(ch))
    rec(n)
    return ''.join(parts)

def xpath_text(n):
    return node_text(n).strip()

def css_text(n):
    return node_text(n).strip()

# XPath subset
class XPathParseError(Exception): pass

def split_xpath(path):
    steps=[]; i=0; axis='child'
    if path.startswith('/'):
        if path.startswith('//'):
            axis='desc'; i=2
        else:
            axis='child'; i=1
    while i < len(path):
        if path.startswith('//',i): axis='desc'; i+=2; continue
        if path[i]=='/': axis='child'; i+=1; continue
        st=i; br=0; quote=None
        while i<len(path):
            c=path[i]
            if quote:
                if c==quote: quote=None
            else:
                if c in ('"',"'"): quote=c
                elif c=='[': br+=1
                elif c==']': br-=1
                elif br==0 and path.startswith('//',i): break
                elif br==0 and c=='/': break
            i+=1
        token=path[st:i].strip()
        if token: steps.append((axis,token))
        axis='child'
    return steps

def parse_step(tok):
    preds=[]
    base=''; i=0
    m=re.match(r'^([^\[]*)',tok); base=m.group(1).strip(); i=len(m.group(0))
    while i < len(tok):
        if tok[i]!='[': raise XPathParseError()
        j=i+1; br=1; quote=None
        while j<len(tok):
            c=tok[j]
            if quote:
                if c==quote: quote=None
            else:
                if c in ('"',"'"): quote=c
                elif c=='[': br+=1
                elif c==']':
                    br-=1
                    if br==0: break
            j+=1
        if j>=len(tok): raise XPathParseError()
        preds.append(tok[i+1:j].strip()); i=j+1
    return base, preds

def matches_base(n,base):
    if not isinstance(n,Node): return False
    if base in ('','*'): return True
    return n.tag==base

def apply_pred(nodes,pred):
    pred=pred.strip()
    if re.fullmatch(r'\d+', pred):
        idx=int(pred)
        return [n for n in nodes if sibling_index(n)==idx]
    m=re.fullmatch(r'position\(\)\s*=\s*(\d+)', pred)
    if m:
        idx=int(m.group(1)); return [n for n in nodes if sibling_index(n)==idx]
    if pred=='last()':
        return [n for n in nodes if sibling_index(n)==sibling_count(n)]
    m=re.fullmatch(r'@([\w:.-]+)\s*=\s*(["\'])(.*?)\2', pred)
    if m:
        name=m.group(1); val=m.group(3)
        return [n for n in nodes if node_attr(n,name)==val]
    m=re.fullmatch(r'([\w:.-]+)\s*=\s*(["\'])(.*?)\2', pred)
    if m:
        cn=m.group(1); val=m.group(3)
        return [n for n in nodes if any(c.tag==cn and xpath_text(c)==val for c in element_children(n))]
    m=re.fullmatch(r'contains\(([^,]+),\s*(["\'])(.*?)\2\)', pred)
    if m:
        what=m.group(1).strip(); sub=m.group(3)
        res=[]
        for n in nodes:
            txt=''
            if what in ('.','text()'): txt=xpath_text(n)
            else:
                vals=[xpath_text(c) for c in element_children(n) if c.tag==what]
                txt=''.join(vals)
            if sub in txt: res.append(n)
        return res
    # unsupported predicate: no matches, as the reference is quiet for many unsupported CSS-like cases
    return []

def sibling_index(n):
    if not n.parent: return 1
    same=[c for c in element_children(n.parent) if c.tag==n.tag]
    return same.index(n)+1 if n in same else 1

def sibling_count(n):
    if not n.parent: return 1
    return len([c for c in element_children(n.parent) if c.tag==n.tag])

def eval_xpath(root, expr, single=False):
    expr=expr.strip()
    if not expr: raise XPathParseError()
    # Scalar functions for -x only; caller decides whether to use them.
    m=re.fullmatch(r'string\((.*)\)', expr)
    if m:
        vals=eval_xpath(root,m.group(1),False)
        if not vals: return [TextResult('')]
        v=vals[0]
        if isinstance(v,AttrResult): return [TextResult(v.value)]
        if isinstance(v,TextResult): return [TextResult(v.text.strip())]
        return [TextResult(xpath_text(v))]
    m=re.fullmatch(r'count\((.*)\)', expr)
    if m:
        vals=eval_xpath(root,m.group(1),False)
        return [TextResult(str(len(vals)))]
    try:
        steps=split_xpath(expr)
        if not steps: raise XPathParseError()
    except Exception:
        raise XPathParseError()
    current=[root]
    for axis,tok in steps:
        base,preds=parse_step(tok)
        # attributes/text steps
        if base.startswith('@'):
            name=base[1:]
            out=[]
            for c in current:
                if not isinstance(c,Node): continue
                for k,v in c.attrs:
                    if name=='*' or k==name: out.append(AttrResult(k,v,c))
            current=out; continue
        if base=='text()':
            out=[]
            for c in current:
                if isinstance(c,Node):
                    for ch in c.children:
                        if not isinstance(ch,Node) and str(ch).strip(): out.append(TextResult(str(ch),c))
            current=out; continue
        cand=[]
        for c in current:
            if not isinstance(c,Node): continue
            search = all_desc(c) if axis=='desc' else element_children(c)
            cand.extend([n for n in search if matches_base(n,base)])
        for p in preds:
            cand=apply_pred(cand,p)
        current=cand
    if single and current: return [current[0]]
    return current

# CSS selector subset
class CSSParseError(Exception): pass

def split_css_groups(sel):
    groups=[]; st=0; br=0; par=0; quote=None
    for i,c in enumerate(sel):
        if quote:
            if c==quote: quote=None
        else:
            if c in ('"',"'"): quote=c
            elif c=='[': br+=1
            elif c==']': br-=1
            elif c=='(': par+=1
            elif c==')': par-=1
            elif c==',' and br==0 and par==0:
                groups.append(sel[st:i].strip()); st=i+1
    groups.append(sel[st:].strip())
    return groups

def parse_simple_selector(s):
    if not s: raise CSSParseError()
    out={'tag':None,'id':None,'classes':[],'attrs':[],'pseudos':[]}
    i=0
    if s[i]=='*': out['tag']='*'; i+=1
    elif re.match(r'[A-Za-z_][\w-]*', s[i:]):
        m=re.match(r'[A-Za-z_][\w-]*', s[i:]); out['tag']=m.group(0); i+=len(m.group(0))
    while i < len(s):
        c=s[i]
        if c=='#':
            m=re.match(r'#([\w-]+)', s[i:])
            if not m: raise CSSParseError()
            out['id']=m.group(1); i+=len(m.group(0))
        elif c=='.':
            m=re.match(r'\.([\w-]+)', s[i:])
            if not m: raise CSSParseError()
            out['classes'].append(m.group(1)); i+=len(m.group(0))
        elif c=='[':
            j=s.find(']',i+1)
            if j<0: raise CSSParseError()
            cont=s[i+1:j].strip()
            m=re.fullmatch(r'([\w:-]+)(?:\s*=\s*(["\']?)(.*?)\2)?',cont)
            if not m: raise CSSParseError()
            out['attrs'].append((m.group(1), m.group(3) if m.group(2) or m.group(3) else None)); i=j+1
        elif c==':':
            if s.startswith(':first-child',i): out['pseudos'].append(('first',None)); i+=12
            elif s.startswith(':nth-child',i):
                m=re.match(r':nth-child\((\d+)\)',s[i:])
                if not m: raise CSSParseError()
                out['pseudos'].append(('nth',int(m.group(1)))); i+=len(m.group(0))
            elif s.startswith(':contains',i):
                m=re.match(r':contains\((["\'])(.*?)\1\)',s[i:])
                if not m: raise CSSParseError()
                out['pseudos'].append(('contains',m.group(2))); i+=len(m.group(0))
            elif s.startswith(':not',i):
                m=re.match(r':not\((.*?)\)',s[i:])
                if not m: raise CSSParseError()
                out['pseudos'].append(('not',parse_simple_selector(m.group(1).strip()))); i+=len(m.group(0))
            else:
                raise CSSParseError()
        else:
            raise CSSParseError()
    if out['tag'] is None: out['tag']='*'
    return out

def parse_css_sequence(group):
    seq=[]; i=0; comb='desc'; n=len(group)
    while i<n:
        while i<n and group[i].isspace():
            i+=1
            if seq: comb='desc'
        if i>=n: break
        if group[i]=='>': comb='child'; i+=1; continue
        if group[i]=='+': comb='adj'; i+=1; continue
        st=i; br=par=0; quote=None
        while i<n:
            c=group[i]
            if quote:
                if c==quote: quote=None
            else:
                if c in ('"',"'"): quote=c
                elif c=='[': br+=1
                elif c==']': br-=1
                elif c=='(': par+=1
                elif c==')': par-=1
                elif br==0 and par==0 and (c=='>' or c=='+' or c.isspace()): break
            i+=1
        simple=group[st:i].strip()
        if not simple: raise CSSParseError()
        seq.append((comb,parse_simple_selector(simple)))
        comb='desc'
    return seq

def css_match(n, simple):
    if not isinstance(n,Node) or n.tag is None: return False
    if simple['tag']!='*' and n.tag!=simple['tag']: return False
    if simple['id'] is not None and node_attr(n,'id')!=simple['id']: return False
    cls=node_attr(n,'class') or ''
    classes=cls.split()
    for c in simple['classes']:
        if c not in classes: return False
    for k,v in simple['attrs']:
        av=node_attr(n,k)
        if av is None: return False
        if v is not None and av!=v: return False
    for kind,val in simple['pseudos']:
        if kind=='first':
            if css_element_index(n)!=1: return False
        elif kind=='nth':
            if css_element_index(n)!=val: return False
        elif kind=='contains':
            if val not in css_text(n): return False
        elif kind=='not':
            if css_match(n,val): return False
    return True

def css_element_index(n):
    if not n.parent: return 1
    elems=element_children(n.parent)
    return elems.index(n)+1 if n in elems else 1

def next_element_sibling(n):
    if not n.parent: return None
    elems=element_children(n.parent)
    try:
        idx=elems.index(n)
        return elems[idx+1] if idx+1<len(elems) else None
    except ValueError: return None

def eval_css(root, selector):
    if selector=='': return None  # means no query was really requested
    try:
        groups=split_css_groups(selector)
        parsed=[parse_css_sequence(g) for g in groups]
    except Exception:
        return []
    matches=[]; seen=set()
    for seq in parsed:
        current=[root]
        for comb,simple in seq:
            cand=[]
            if comb=='desc':
                for c in current:
                    if isinstance(c,Node): cand.extend([n for n in all_desc(c) if css_match(n,simple)])
            elif comb=='child':
                for c in current:
                    if isinstance(c,Node): cand.extend([n for n in element_children(c) if css_match(n,simple)])
            elif comb=='adj':
                for c in current:
                    n=next_element_sibling(c)
                    if n is not None and css_match(n,simple): cand.append(n)
            current=cand
        for n in current:
            if id(n) not in seen:
                seen.add(id(n)); matches.append(n)
    matches.sort(key=lambda n:n.order)
    return matches

# Serialization helpers

def serialize_xml_node(n):
    if isinstance(n,AttrResult):
        return '<'+n.name+'>'+esc_text_raw(n.value)+'</'+n.name+'>'
    if isinstance(n,TextResult): return esc_text_raw(n.text)
    attrs=''.join(' '+k+'="'+esc_attr(v)+'"' for k,v in n.attrs)
    elems=''.join(serialize_xml_child(ch) for ch in n.children)
    if elems=='': return '<'+n.tag+attrs+'/>'
    return '<'+n.tag+attrs+'>'+elems+'</'+n.tag+'>'

def serialize_xml_child(ch):
    if isinstance(ch,Node): return serialize_xml_node(ch)
    return esc_text_raw(str(ch))

def esc_text_raw(t):
    # Raw serializer should be parseable; formatter will decode/wrap as needed.
    return str(t).replace('&','&amp;').replace('<','&lt;')

def serialize_html_node(n, top=True):
    attrs=''.join(' '+k+'="'+esc_attr(v)+'"' for k,v in n.attrs)
    if n.void:
        if top:
            return '<'+n.tag+attrs+'></'+n.tag+'>'
        return '<'+n.tag+attrs+'>'
    body=''.join(serialize_html_child(ch) for ch in n.children)
    return '<'+n.tag+attrs+'>'+body+'</'+n.tag+'>'

def serialize_html_child(ch):
    if isinstance(ch,Node): return serialize_html_node(ch,False)
    return str(ch).replace('&','&amp;').replace('<','&lt;')

# JSON conversion

def strip_prefix(name):
    if ':' in name: return name.split(':',1)[1]
    return name

def collapse_text(n):
    parts=[]
    def elem_value(e):
        local=[]
        for ch in e.children:
            if isinstance(ch,Node):
                sub=elem_value(ch)
                if sub==[]:
                    local.append('')
                else:
                    local.extend(sub)
            else:
                t=str(ch).strip()
                if t: local.append(t)
        return local
    parts=elem_value(n)
    if not parts:
        return ''
    return '\n'.join(parts)

def convert_json_node(n, level, max_depth):
    if max_depth >=0 and level >= max_depth:
        return collapse_text(n)
    attrs=[('@'+strip_prefix(k),v) for k,v in n.attrs]
    elems=element_children(n)
    texts=[]
    for ch in n.children:
        if not isinstance(ch,Node):
            t=str(ch).strip()
            if t: texts.append(t)
    if not attrs and not elems:
        if texts: return '\n'.join(texts)
        return OrderedDict()
    obj={}
    if texts: obj['#text']='\n'.join(texts)
    for k,v in attrs: obj[k]=v
    groups=defaultdict(list)
    for e in elems: groups[strip_prefix(e.tag)].append(e)
    for k,arr in groups.items():
        if len(arr)==1: obj[k]=convert_json_node(arr[0],level+1,max_depth)
        else: obj[k]=[convert_json_node(x,level+1,max_depth) for x in arr]
    return OrderedDict((k,obj[k]) for k in sorted(obj.keys()))

def json_from_xml(data,opt):
    if data=='':
        if opt.html:
            return '', 'error while parsing XML: xmlquery: invalid XML document'
        val=OrderedDict([('text','')])
        return dumps_json(val,opt.compact)+'\n', None
    if '<![CDATA[' in data:
        return '', "error while parsing JSON: invalid character '<' looking for beginning of value"
    if data.strip() and not data.lstrip().startswith('<'):
        return '', 'error while parsing XML: xmlquery: invalid XML document'
    try:
        root=parse_xml_tree(data, strict=True)
    except ValueError as e:
        msg=str(e)
        if msg.startswith("invalid character"):
            return '', 'error while parsing JSON: '+msg
        if msg.startswith('xmlquery'):
            return '', 'error while parsing XML: '+msg
        return '', 'error while parsing XML: '+msg
    top=OrderedDict()
    for ch in root.children:
        if isinstance(ch,Node):
            key=strip_prefix(ch.tag)
            val=convert_json_node(ch,0,opt.depth)
            if key in top:
                if not isinstance(top[key],list): top[key]=[top[key]]
                top[key].append(val)
            else:
                top[key]=val
    if not top:
        top['text']=''
    top=OrderedDict((k,top[k]) for k in sorted(top.keys()))
    return dumps_json(top,opt.compact)+'\n', None

def json_string(s): return json.dumps(s, ensure_ascii=False)

def dumps_json(v,compact=False,level=0):
    if isinstance(v,OrderedDict) or isinstance(v,dict):
        items=list(v.items())
        if compact:
            return '{'+','.join(json_string(k)+': '+dumps_json(val,True,level+1) for k,val in items)+'}'
        if not items:
            return '{\n\n'+'  '*level+'}'
        lines=[]
        for idx,(k,val) in enumerate(items):
            comma=',' if idx<len(items)-1 else ''
            lines.append('  '*(level+1)+json_string(k)+': '+dumps_json(val,False,level+1)+comma)
        return '{\n'+'\n'.join(lines)+'\n'+'  '*level+'}'
    if isinstance(v,list):
        if compact:
            return '['+','.join(dumps_json(x,True,level+1) for x in v)+']'
        if not v: return '[]'
        lines=[]
        for idx,x in enumerate(v):
            comma=',' if idx<len(v)-1 else ''
            lines.append('  '*(level+1)+dumps_json(x,False,level+1)+comma)
        return '[\n'+'\n'.join(lines)+'\n'+'  '*level+']'
    if isinstance(v,str): return json_string(v)
    return json.dumps(v, ensure_ascii=False)

# Operations

def run_xpath(data,opt,single=False):
    if data=='': return '', 'xmlquery: invalid XML document'
    try:
        root=parse_xml_tree(data, strict=False)
        # scalar functions are intentionally ignored by --extract, matching reference behavior
        if single and re.match(r'\s*(string|count)\s*\(', opt.extract):
            return '', None
        expr=opt.xpath if opt.xpath_set and opt.xpath!='' else opt.extract
        if '[' in expr and expr.count('[')!=expr.count(']'):
            return '', 'unable to parse the XPath query'
        vals=eval_xpath(root,expr,single)
    except XPathParseError:
        return '', 'unable to parse the XPath query'
    except Exception:
        vals=[]
    out=[]
    if opt.node:
        for v in vals:
            if isinstance(v,AttrResult): raw=serialize_xml_node(v)
            elif isinstance(v,TextResult): raw=esc_text_raw(v.text)
            else: raw=serialize_xml_node(v)
            formatted,err=format_xml(raw,opt)
            out.append(formatted)
    else:
        for v in vals:
            if isinstance(v,AttrResult): out.append(v.value+'\n')
            elif isinstance(v,TextResult): out.append(v.text.strip()+'\n')
            else: out.append(xpath_text(v)+'\n')
    return ''.join(out), None

def run_css(data,opt):
    root=parse_html_tree(data, True) if opt.html else parse_xml_tree(data, strict=False)
    matches=eval_css(root,opt.query)
    if matches is None:
        return None, None
    out=[]
    for n in matches:
        if opt.attr!='':
            v=node_attr(n,opt.attr)
            out.append((v if v is not None else '')+'\n')
        elif opt.node:
            raw=serialize_html_node(n,True) if opt.html else serialize_xml_node(n)
            formatted,err=(format_html(raw,opt) if opt.html else format_xml(raw,opt))
            out.append(formatted)
        else:
            out.append(css_text(n)+'\n')
    return ''.join(out), None

def process_data(data,opt):
    # Operation precedence: XPath, extract, CSS query, JSON, formatter.
    if opt.xpath_set and opt.xpath!='':
        return run_xpath(data,opt,False)
    if opt.extract!='':
        return run_xpath(data,opt,True)
    if opt.query_set and opt.query!='':
        return run_css(data,opt)
    if opt.json:
        return json_from_xml(data,opt)
    if opt.html:
        return format_html(data,opt)
    return format_xml(data,opt)


def read_file(path):
    try:
        if os.path.isdir(path):
            return '', None
        with open(path,'rb') as f:
            return f.read().decode('utf-8','replace'), None
    except Exception as e:
        return None, str(e)


def main(argv):
    opt=parse_args(argv)
    if opt.in_place and len(opt.files)!=1:
        # With no input at all the reference displays help; with piped data or >1 files it reports an in-place error.
        stdin_data=''
        if len(opt.files)==0:
            try:
                stdin_data=sys.stdin.buffer.read().decode('utf-8','replace')
            except Exception: stdin_data=''
            if stdin_data=='':
                sys.stdout.write(HELP); return 0
        sys.stderr.write('Error: in-place formatting requires a file path (and only one file path)\n')
        return 0
    outputs=[]
    if opt.files:
        for path in opt.files:
            data,err=read_file(path)
            if err:
                sys.stderr.write('Error: '+err+'\n'); return 1
            out,operr=process_data(data,opt)
            if operr:
                sys.stdout.write((out or '')+'Error: '+operr+'\n')
                return 1
            if opt.in_place:
                with open(path,'w',encoding='utf-8') as f: f.write(out or '')
            else:
                outputs.append(out or '')
    else:
        data=sys.stdin.buffer.read().decode('utf-8','replace')
        out,operr=process_data(data,opt)
        if operr:
            sys.stdout.write((out or '')+'Error: '+operr+'\n')
            return 1
        outputs.append(out or '')
    if not opt.in_place:
        sys.stdout.write(''.join(outputs))
    return 0

if __name__=='__main__':
    sys.exit(main(sys.argv[1:]))
